<script setup lang="ts">import {onMounted,ref} from 'vue';import {initCookieConsent,showCookiePreferences} from '~/lib/cookieConsent';const config=useRuntimeConfig();const theme=ref<'light'|'dark'>('light');const year=new Date().getFullYear();useHead({title:'Embeddable Event Photo Gallery Nuxt.js Component | Qrati Connect',meta:[{name:'description',content:'Embed a live event photo gallery in Nuxt.js with guest uploads, lightbox, reactions, and contest leaderboards.'},{name:'robots',content:'index, follow'},{property:'og:type',content:'website'},{property:'og:url',content:'https://qrati.com/connect/nuxtjs-example'}],link:[{rel:'canonical',href:'https://qrati.com/connect/nuxtjs-example'},{rel:'icon',href:'/favicon.svg',type:'image/svg+xml'}]});function applyTheme(next:'light'|'dark'){theme.value=next;document.documentElement.dataset.theme=next;document.documentElement.classList.toggle('dark',next==='dark');localStorage.setItem('qc-theme',next)}onMounted(()=>{const saved=localStorage.getItem('qc-theme') as 'light'|'dark'|null;applyTheme(saved==='dark'||saved==='light'?saved:'light');void initCookieConsent(config.public.gtmId)})</script>
<template><button class="theme-toggle" type="button" @click="applyTheme(theme==='dark'?'light':'dark')">{{theme==='dark'?'☀️ Light':'🌙 Dark'}}</button><div class="page-frame"><header class="hero"><p class="hero-kicker">Embeddable Nuxt.js Gallery SDK</p><h1><a href="https://qrati.com" target="_blank" rel="noopener noreferrer">Qrati</a> Connect inside a Nuxt.js host site</h1><p class="hero-copy">A drop-in web component for live event photo galleries with guest uploads, full-screen lightbox, emoji reactions, and contest leaderboards. Nuxt.js renders the host page while Qrati Connect handles the gallery.</p><nav class="action-pills"><a href="https://github.com/qrati-labs/qrati-connect-nuxtjs-example" target="_blank" rel="noopener noreferrer">View on GitHub</a><a href="https://www.npmjs.com/package/@qratilabs/qrati-connect" target="_blank" rel="noopener noreferrer">npm package</a></nav></header><main><section class="widget-frame" aria-label="Interactive Nuxt.js Event Gallery"><h2 class="sr-only">Live Event Photo Gallery Component</h2><qrati-connect :organization-id="config.public.organizationId" :theme="theme" router="hash" /></section><section class="seo-section"><p class="seo-kicker">Event Gallery Features</p><h2>Why Developers Choose Qrati Connect</h2><div class="grid"><article><b>🖼️ Live Event Photo Wall</b><p>Responsive masonry gallery, blurhash loading, and keyboard-friendly lightbox.</p></article><article><b>📸 Guest Media Uploads</b><p>QR or direct uploads with client-side compression and HEIC conversion.</p></article><article><b>⭐ Reactions &amp; Contests</b><p>Emoji reactions, star ratings, and real-time contest rankings.</p></article><article><b>⚡ Native Web Component</b><p>Use the same custom element in Nuxt, Vue, or any host with reactive theme binding.</p></article></div></section><section class="seo-section"><p class="seo-kicker">Developer Integration</p><h2>Embed in 3 Simple Steps</h2><pre><code>pnpm add @qratilabs/qrati-connect\n\n&lt;qrati-connect organization-id="your-organization-id" theme="light" router="hash"&gt;&lt;/qrati-connect&gt;</code></pre></section><section class="seo-section"><p class="seo-kicker">Common Questions</p><h2>Frequently Asked Questions</h2><div class="faq-list"><details open><summary>How do I embed an event photo gallery in Nuxt.js?</summary><p>Load the Qrati Connect element and render the custom element with your organization ID.</p></details><details><summary>Can attendees upload photos?</summary><p>Yes, when uploads are enabled in your Qrati organization settings.</p></details><details><summary>How does Nuxt.js handle theme sync?</summary><p>Bind the element theme to reactive state; toggling state updates the element immediately.</p></details><details><summary>Does it support dark mode?</summary><p>Yes. Set theme to light or dark.</p></details><details><summary>Can I run photo contests?</summary><p>Yes. Contest rankings, reactions, and ratings are configured in Qrati.</p></details></div></section><section class="seo-section cta"><p class="seo-kicker">Host on Qrati · Embed Anywhere</p><h2>Host Your Event on Qrati. <span>Stream the Live Gallery on Your Website.</span></h2><p>Set up your event, let attendees upload, then embed the live gallery in your Nuxt.js app.</p><a href="https://qrati.com" target="_blank" rel="noopener noreferrer">Host Your Event on Qrati →</a></section></main><footer class="footer"><img src="https://assets.qrati.com/images/qrati-connect-logo-square.png" alt="Qrati Connect logo" referrerpolicy="no-referrer"><span><b><i>Qrati</i> Connect</b><small>Elevate your event experience.</small></span><nav><a href="https://qrati.com">qrati.com</a><a href="https://qrati.com/pricing">Pricing</a><button type="button" @click="showCookiePreferences">Cookie Preferences</button></nav><small>© {{year}} Qrati Labs. All rights reserved.</small></footer></div></template>
